import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "Upload a document",
    { tag: "@DOC-01" },
    async ({ apiAs }) => {
      // Background: signed in as member@northwind.test
      const member = await apiAs("member");

      // Background: a vendor in status "draft"
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC01 Vendor"),
          category: "services",
          contact_email: `doc01-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@vendor.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = (await createResponse.json()) as { id: string; status: string };
      expect(vendor.status).toBe("draft");

      // When I upload "insurance_certificate.txt" as kind "insurance_certificate"
      const fileName = "insurance_certificate.txt";
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: fileName,
            mimeType: "text/plain",
            buffer: readFileSync(sample(fileName)),
          },
        },
      });

      // Then the response status is 201
      expect(uploadResponse.status()).toBe(201);
      const document = (await uploadResponse.json()) as {
        id: string;
        vendor_id: string;
        kind: string;
        status: string;
      };
      expect(document.vendor_id).toBe(vendor.id);
      expect(document.kind).toBe("insurance_certificate");

      // And the document status is "processing"
      expect(document.status).toBe("processing");

      // And an audit event "document.uploaded" is recorded
      const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
      expect(auditResponse.status()).toBe(200);
      const trail = (await auditResponse.json()) as { items: { action: string }[] };
      expect(trail.items.map((event) => event.action)).toContain("document.uploaded");
    },
  );
});
